"use client"

import * as React from "react"

import { type PageGroup, formatPageRanges } from "@/lib/retab"
import { cn } from "@/lib/utils"
import { type PageRangesModel, usePageRanges } from "@/hooks/use-retab"

interface PageGroupContextValue extends PageRangesModel {
  activeIndex: number | null
  setActiveIndex: (index: number | null) => void
  confidences?: (number | null)[]
}

const PageGroupContext = React.createContext<PageGroupContextValue | null>(null)

function usePageGroupContext(part: string): PageGroupContextValue {
  const ctx = React.useContext(PageGroupContext)
  if (!ctx) {
    throw new Error(`<PageGroupViewer.${part}> must be used within <PageGroupViewer.Root>`)
  }
  return ctx
}

export interface PageGroupRootProps {
  groups: PageGroup[]
  pageCount?: number
  confidences?: (number | null)[]
  children: React.ReactNode
}

function PageGroupRoot({
  groups,
  pageCount,
  confidences,
  children,
}: PageGroupRootProps) {
  const model = usePageRanges(groups, pageCount)
  const [activeIndex, setActiveIndex] = React.useState<number | null>(null)
  const value = React.useMemo(
    () => ({ ...model, activeIndex, setActiveIndex, confidences }),
    [model, activeIndex, confidences]
  )
  return (
    <PageGroupContext.Provider value={value}>
      {children}
    </PageGroupContext.Provider>
  )
}

export function PageGroupTimeline({ className }: { className?: string }) {
  const { pageCount, pageOwners, hueFor, activeIndex, setActiveIndex } =
    usePageGroupContext("Timeline")
  if (pageCount <= 0) return null
  return (
    <div className={cn("flex flex-col gap-1.5", className)}>
      <span className="text-xs font-medium text-muted-foreground">
        {pageCount} page{pageCount === 1 ? "" : "s"}
      </span>
      <div
        data-slot="page-group-timeline"
        className="flex gap-0.5 overflow-hidden rounded-md"
      >
        {Array.from({ length: pageCount }, (_, i) => {
          const page = i + 1
          const owners = pageOwners.get(page) ?? []
          const owner = owners[0]
          const dimmed = activeIndex != null && !owners.includes(activeIndex)
          return (
            <div
              key={page}
              title={`Page ${page}`}
              onMouseEnter={() => owner != null && setActiveIndex(owner)}
              onMouseLeave={() => setActiveIndex(null)}
              className="h-6 flex-1 rounded-[3px] transition-opacity"
              style={{
                backgroundColor:
                  owner == null
                    ? "hsl(var(--muted))"
                    : `hsl(${hueFor(owner)} 70% 55%)`,
                opacity: dimmed ? 0.25 : 1,
              }}
            />
          )
        })}
      </div>
    </div>
  )
}

export function PageGroupList({
  unitLabel = "group",
  className,
}: {
  unitLabel?: string
  className?: string
}) {
  const { groups, hueFor, confidences, activeIndex, setActiveIndex } =
    usePageGroupContext("List")
  return (
    <div className={cn("flex flex-col gap-1.5", className)}>
      <span className="text-xs font-medium text-muted-foreground">
        {groups.length} {unitLabel}
        {groups.length === 1 ? "" : "s"}
      </span>
      <ul className="flex flex-col gap-1.5">
        {groups.map((group) => {
          const confidence = confidences?.[group.index] ?? null
          const active = activeIndex === group.index
          return (
            <li
              key={`${group.label}-${group.index}`}
              data-active={active}
              data-slot="page-group-item"
              onMouseEnter={() => setActiveIndex(group.index)}
              onMouseLeave={() => setActiveIndex(null)}
              className={cn(
                "flex items-center gap-3 rounded-lg border p-2.5 transition-colors",
                active ? "border-border bg-muted/50" : "border-transparent"
              )}
            >
              <span
                aria-hidden
                className="size-3 shrink-0 rounded-full"
                style={{ backgroundColor: `hsl(${hueFor(group.index)} 70% 55%)` }}
              />
              <div className="min-w-0 flex-1">
                <div className="truncate text-sm font-medium">{group.label}</div>
                <div className="font-mono text-xs text-muted-foreground">
                  {group.pages.length} page{group.pages.length === 1 ? "" : "s"} ·{" "}
                  {formatPageRanges(group.pages)}
                </div>
              </div>
              {confidence != null ? (
                <span className="shrink-0 text-xs tabular-nums text-muted-foreground">
                  {Math.round(confidence * 100)}%
                </span>
              ) : null}
            </li>
          )
        })}
      </ul>
    </div>
  )
}

/** Renders previews for the active group's pages via a render prop. */
export function PageGroupPreview({
  renderPage,
}: {
  renderPage: (page: number, group: PageGroup) => React.ReactNode
}) {
  const { groups, activeIndex } = usePageGroupContext("Preview")
  if (activeIndex == null) return null
  const group = groups.find((g) => g.index === activeIndex)
  if (!group) return null
  return (
    <div className="flex flex-wrap gap-2">
      {group.pages.map((p) => (
        <React.Fragment key={p}>{renderPage(p, group)}</React.Fragment>
      ))}
    </div>
  )
}

export interface PageGroupViewerProps {
  groups: PageGroup[]
  pageCount?: number
  unitLabel?: string
  confidences?: (number | null)[]
  renderPage?: (page: number, group: PageGroup) => React.ReactNode
  className?: string
}

/** Convenience component composing the page-group parts. */
export function PageGroupViewer({
  groups,
  pageCount,
  unitLabel = "group",
  confidences,
  renderPage,
  className,
}: PageGroupViewerProps) {
  return (
    <PageGroupRoot groups={groups} pageCount={pageCount} confidences={confidences}>
      <div className={cn("flex flex-col gap-4 p-4", className)}>
        <PageGroupTimeline />
        <PageGroupList unitLabel={unitLabel} />
        {renderPage ? <PageGroupPreview renderPage={renderPage} /> : null}
      </div>
    </PageGroupRoot>
  )
}

PageGroupViewer.Root = PageGroupRoot
PageGroupViewer.Timeline = PageGroupTimeline
PageGroupViewer.List = PageGroupList
PageGroupViewer.Preview = PageGroupPreview
